constexpr bool HasDeviceOffset(uint32_t reference) {
  switch (reference) {
    case 10920:  // shader GPR allocation: only XD3D_SetShaderGprAllocation writes it, inlined in Gears
    case 16552:  // the completed frame: GTA's flip interrupt (829D4C48) counts it, Gears' Swap writes the flip register itself and keeps no such counter
      return false;
    default:
      return true;
  }
}

// The dirty words (device + 0 to 32, a bit per thing changed since the last draw): count bits
// of this game's word from bit (from the bottom) hold GTA IV's reference_word from reference_bit.
struct DirtyRun {
  uint32_t reference_word, reference_bit, word, bit, count;
};
